import{_ as e,c as a,o,ae as r}from"./chunks/framework.Bi6zybwU.js";const m=JSON.parse('{"title":"Export Ninja Tables (CSV/JSON)","description":"Export Ninja Tables (CSV/JSON)","frontmatter":{"title":"Export Ninja Tables (CSV/JSON)","description":"Export Ninja Tables (CSV/JSON)"},"headers":[],"relativePath":"guide/import-export/export-ninja-tables-csv-json.md","filePath":"guide/import-export/export-ninja-tables-csv-json.md"}'),n={name:"guide/import-export/export-ninja-tables-csv-json.md"};function s(i,t,l,p,c,b){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="export-ninja-tables-csv-json" tabindex="-1">Export Ninja Tables (CSV/JSON) <a class="header-anchor" href="#export-ninja-tables-csv-json" aria-label="Permalink to &quot;Export Ninja Tables (CSV/JSON)&quot;">​</a></h1><p>It is quite easy &amp; straightforward to export table data from <strong>Ninja Tables</strong>. This plugin is designed to make things simpler for the users &amp; improve the overall user experience. Let&#39;s dive into the article to learn how the Ninja Tables export works.</p><ul><li>First, navigate to **All Tables **in the Ninja tables. Pick the preferred table you want to export.</li><li>Then move to the <strong>Import-Export</strong> tab. <img src="https://ninjatables.com/wp-content/uploads/2022/09/01-3-scaled.webp" alt="Import - Export"></li><li>The **Export Data **option can be found below the **Import Data **option, on the **Import-Export **menu. <img src="https://ninjatables.com/wp-content/uploads/2022/09/02-3-scaled.webp" alt="Export Data"></li><li>There are two export file formats provided by Ninja Tables. **CSV **&amp; **JSON, **now you just need to choose the option. <img src="https://ninjatables.com/wp-content/uploads/2022/09/03-3-scaled.webp" alt="File Format"></li><li>Lastly, save the table data on your computer by clicking on the **Export **button. When you export a particular table in CSV format, you&#39;ll just export the table data. However, exporting the JSON file lets you export the Table Styling with the table data. So there&#39;s no need to customize your table from scratch. Export table data from Ninja Tables and use it in a new table or simply send the CSV/JSON file to someone who needs it.</li></ul>',3)])])}const h=e(n,[["render",s]]);export{m as __pageData,h as default};
